export const sendMail = async (
    formData: Record<string, any>,
    title: string,
    files: File[],
    token: string,
    fieldLabels?: Record<string, string>
) => {
    const email = 'hpegemsgenericmailbox@hpe.com';
    // Compose subject with entity and jurisdiction if available
    let subject = title;
    if (formData.legalEntity && formData.jurisdiction) {
        subject = `${title} - ${formData.legalEntity} - ${formData.jurisdiction}`;
    } else if (formData.legalEntity) {
        subject = `${title} - ${formData.legalEntity}`;
    } else if (formData.jurisdiction) {
        subject = `${title} - ${formData.jurisdiction}`;
    }
    const { fileName, ...filteredFormData } = formData;
    // Debug log
    console.log('fieldLabels:', fieldLabels);
    console.log('filteredFormData:', filteredFormData);
    const bodyContent = Object.entries(filteredFormData)
        .map(([key, value]) => {
            const cleanKey = key.trim();
            return `<b>${fieldLabels && fieldLabels[cleanKey] ? fieldLabels[cleanKey] : cleanKey}:</b> ${value}`;
        })
        .join('<br/>');

    let attachments = [];
    if (files && files.length > 0) {
        for (const file of files) {
            const fileBuffer = await file.arrayBuffer();
            const uint8Arr = new Uint8Array(fileBuffer);
            attachments.push({
                '@odata.type': '#microsoft.graph.fileAttachment',
                name: file.name,
                contentBytes: uint8ToBase64(uint8Arr),
            });
        }
    }

    const mail = {
        message: {
            subject,
            body: {
                contentType: 'HTML',
                content: bodyContent,
            },
            toRecipients: [
                {
                    emailAddress: {
                        address: email,
                    },
                },
            ],
            attachments,
        },
        saveToSentItems: 'true',
    };

    const response = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
        method: 'POST',
        headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
        },
        body: JSON.stringify(mail),
    });

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to send mail: ${response.status} ${errorText}`);
    }
};

const uint8ToBase64 = (uint8Arr: Uint8Array) => {
    let binary = '';
    const len = uint8Arr.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(uint8Arr[i]);
    }
    return btoa(binary);
}