import React from "react";
import { MemoryRouter as Router, Routes, Route } from "react-router-dom";
import Login from "../components/pages/login/page";
import Home from "../components/pages/home/page";
import Director from "../components/pages/dropdowns/director";
import Ownership from "../components/pages/dropdowns/ownership";
import Address from "../components/pages/dropdowns/address";
import Legal from "../components/pages/dropdowns/legal";
import Status from "../components/pages/dropdowns/status";
import Name from "../components/pages/dropdowns/name";
import Counsel from "../components/pages/dropdowns/counsel";
import Attorney from "../components/pages/dropdowns/attorney";

const RouterApp: React.FC = () => {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<Login />} />
                <Route path="/home" element={<Home />} />
                <Route path="/Change of Director / Officer" element={<Director />} />
                <Route path="/Change of Ownership" element={<Ownership />} />
                <Route path="/Change of Address" element={<Address />} />
                <Route path="/Change in Legal Form" element={<Legal />} />
                <Route path="/Change of Status and Cessation" element={<Status />} />
                <Route path="/Change of Name" element={<Name />} />
                <Route path="/Change in Country Counsel" element={<Counsel />} />
                <Route path="/Power of Attorney" element={<Attorney />} />
            </Routes>
        </Router>
    );
};

export default RouterApp;