import React from 'react';
import { Stack, Typography, Select, MenuItem, FormControl, InputLabel, AppBar, Box, IconButton, Toolbar, Tooltip } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import UIText from '../../../utilities/textResource';
import { options } from '../../../utilities/dropdown';
import { IoMdArrowRoundBack, IoMdLogOut } from 'react-icons/io';
import logo from '../../../../../assets/logo-filled.png';

const Home: React.FC = () => {
    const navigate = useNavigate();

    const handleChange = (event: any) => {
        const value = event.target.value;
        console.log(value);

        if (value) {
            navigate(`/${value}`);
        }
    };

    // Implement your logout logic here (e.g., clear tokens, redirect to login)
    const handleLogout = () => {
        localStorage.removeItem('access_token');
        navigate('/');
    };

    return (
        <>
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static">
                    <Toolbar sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <Typography sx={{ fontSize: "18px", fontWeight: 500 }}>
                            GEMS Change Request Tool
                        </Typography>
                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="logout"
                                onClick={handleLogout}
                                sx={{ ml: 2 }}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Toolbar>
                </AppBar>
            </Box>

            <Stack
                id="bias-report-home"
                sx={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    marginTop: "12px",
                    gap: "6px",
                }}
            >
                <img src={logo} alt="This is a Phish" style={{ maxWidth: "300px", height: "120px" }} />
                <Typography sx={{ textAlign: "center", paddingLeft: "8px", paddingRight: "8px", fontSize: "15px" }}>
                    {UIText.auth.description}
                </Typography>
            </Stack>

            <Stack alignItems="center" justifyContent="center" mt={2} sx={{ width: '94%', marginLeft: "-9px", px: 2 }}>
                <FormControl fullWidth size="small">
                    <InputLabel id="dropdown-label">Select Request</InputLabel>
                    <Select
                        labelId="dropdown-label"
                        id="dropdown-select"
                        label="Select Request"
                        defaultValue=""
                        onChange={handleChange}
                        renderValue={(selected) => {
                            const option = options.find(opt => opt.value === selected);
                            return option ? option.label : "Select Request";
                        }}
                    >
                        {options.map(option => (
                            <MenuItem key={option.value} value={option.value}>
                                {option.label}
                            </MenuItem>
                        ))}
                    </Select>
                </FormControl>
            </Stack>
        </>
    );
};

export default Home;