import React, { useState } from 'react';
import { Box, TextField, Button, Typography, Stack, AppBar, IconButton, Toolbar, Tooltip, FormControl, FormLabel, RadioGroup, FormControlLabel, Radio } from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { IoCloudUploadOutline } from "react-icons/io5";
import { IoMdArrowRoundBack, IoMdLogOut } from 'react-icons/io';
import { useNavigate } from 'react-router-dom';
import { sendMail } from '../../../services/sendMail';
import { notyf } from '../../../utilities/useToast';
import Loader from '../../loader/Loader';
import { getAccessToken } from '../../auth/authService';

const Counsel: React.FC = () => {
    const navigate = useNavigate();
    const [form, setForm] = useState({
        jurisdiction: '',
        currentCounsel: '',
        currentParalegal: '',
        newCounsel: '',
        newParalegal: '',
        allEntities: '', // yes/no
        affectedEntities: '',
    });
    const [dateEffective, setDateEffective] = useState(null);
    const [files, setFiles] = useState<File[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    const handleBackToHome = () => {
        navigate('/');
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setForm({ ...form, [name]: value });
    };

    const handleRadioChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setForm({ ...form, allEntities: e.target.value, affectedEntities: '' });
    };

    const handleDateChange = (date: any) => {
        setDateEffective(date);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            setFiles(Array.from(e.target.files));
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (
            !form.jurisdiction ||
            !form.currentCounsel ||
            !form.currentParalegal ||
            !form.newCounsel ||
            !form.newParalegal ||
            !dateEffective ||
            !form.allEntities ||
            (form.allEntities === 'no' && !form.affectedEntities) ||
            files.length === 0
        ) {
            notyf.error('Please fill in all fields and upload at least one file.');
            return;
        }
        setIsLoading(true);
        const formData = {
            ...form,
            dateEffective: dateEffective ? dateEffective.format('YYYY-MM-DD') : '',
            fileName: files[0]?.name,
        };
        const fieldLabels = {
            jurisdiction: "Jurisdiction",
            currentCounsel: "Current Country Counsel (Responsible Attorney)",
            currentParalegal: "Current Paralegal (Responsible Paralegal)",
            newCounsel: "New Country Counsel",
            newParalegal: "New Paralegal",
            allEntities: "Does the change apply to all entities within the jurisdiction",
            affectedEntities: "Affected Entities",
            dateEffective: "Date Effective",
            fileName: "Documentary Evidence"
        };
        try {
            const token = await getAccessToken();
            if (!token) throw new Error('No access token found');
            await sendMail(formData, 'Change of Country Counsel / Paralegal', files, token, fieldLabels);
            notyf.success('Email sent successfully!');
            setForm({
                jurisdiction: '',
                currentCounsel: '',
                currentParalegal: '',
                newCounsel: '',
                newParalegal: '',
                allEntities: '',
                affectedEntities: '',
            });
            setFiles([]);
            setDateEffective(null);
        } catch (error) {
            notyf.error('Failed to send email. Please try again.');
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    // Implement your logout logic here (e.g., clear tokens, redirect to login)
    const handleLogout = () => {
        localStorage.removeItem('access_token');
        navigate('/');
    };

    return (
        <>
            {isLoading && <Loader />}
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static">
                    <Toolbar sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Tooltip title="Back to Home" placement="right-start">
                                <IconButton
                                    edge="start"
                                    color="inherit"
                                    aria-label="back"
                                    onClick={handleBackToHome}
                                    sx={{ mr: 2 }}
                                >
                                    <IoMdArrowRoundBack />
                                </IconButton>
                            </Tooltip>
                            <Typography sx={{ fontSize: "16px", fontWeight: 500 }}>
                                Change in Country Counsel
                            </Typography>
                        </Box>
                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="logout"
                                onClick={handleLogout}
                                sx={{ ml: 2 }}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Toolbar>
                </AppBar>
            </Box>

            <Box sx={{ padding: '6px', maxWidth: 'auto', mt: 2 }}>
                <form onSubmit={handleSubmit}>
                    <Stack spacing={2}>
                        <TextField
                            label="Jurisdiction"
                            name="jurisdiction"
                            value={form.jurisdiction}
                            onChange={handleChange}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Current Country Counsel (Responsible Attorney)"
                            name="currentCounsel"
                            value={form.currentCounsel}
                            onChange={handleChange}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Current Paralegal (Responsible Paralegal)"
                            name="currentParalegal"
                            value={form.currentParalegal}
                            onChange={handleChange}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="New Country Counsel"
                            name="newCounsel"
                            value={form.newCounsel}
                            onChange={handleChange}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="New Paralegal"
                            name="newParalegal"
                            value={form.newParalegal}
                            onChange={handleChange}
                            fullWidth
                            size="small"
                        />
                        <FormControl>
                            <LocalizationProvider dateAdapter={AdapterDayjs}>
                                <DatePicker
                                    value={dateEffective}
                                    onChange={handleDateChange}
                                    slotProps={{ textField: { fullWidth: true, size: 'small' } }}
                                />
                            </LocalizationProvider>
                        </FormControl>
                        <FormControl>
                            <FormLabel>Does the change apply to all entities within the jurisdiction</FormLabel>
                            <RadioGroup row name="allEntities" value={form.allEntities} onChange={handleRadioChange}>
                                <FormControlLabel value="yes" control={<Radio />} label="yes" />
                                <FormControlLabel value="no" control={<Radio />} label="no" />
                            </RadioGroup>
                        </FormControl>
                        {form.allEntities === 'no' && (
                            <TextField
                                label="If No, please confirm which entities are effected by change"
                                name="affectedEntities"
                                value={form.affectedEntities}
                                onChange={handleChange}
                                fullWidth
                                size="small"
                            />
                        )}
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                            <Typography variant="body2">
                                Documentary Evidence
                            </Typography>
                            <Box
                                sx={{
                                    border: '2px dashed #bdbdbd',
                                    borderRadius: 2,
                                    padding: "12px 55px",
                                    textAlign: 'center',
                                    cursor: 'pointer',
                                    bgcolor: '#fafbfc',
                                    transition: 'border-color 0.2s',
                                    '&:hover': { borderColor: '#1976d2' }
                                }}
                                onClick={() => document.getElementById('file-upload-input')?.click()}
                                onDrop={e => {
                                    e.preventDefault();
                                    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                                        setFiles(Array.from(e.dataTransfer.files));
                                    }
                                }}
                                onDragOver={e => e.preventDefault()}
                            >
                                <IoCloudUploadOutline style={{ fontSize: 40, color: '#90caf9', marginBottom: '4px' }} />
                                <Typography sx={{ fontSize: "12px" }}>
                                    Drag and drop <Typography component="span" color="primary" sx={{ fontWeight: 500 }}>or <span style={{ textDecoration: 'underline', cursor: 'pointer' }}>browse</span></Typography> to upload
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 1, fontSize: "12px" }}>
                                    PDF, Word, Excel, CSV, Images up to 10MB
                                </Typography>
                                <input
                                    id="file-upload-input"
                                    type="file"
                                    hidden
                                    accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.png,.jpg,.jpeg,.gif"
                                    multiple
                                    onChange={handleFileChange}
                                />
                                {files.length > 0 && (
                                    <Typography variant="body2" color="success.main" sx={{ mt: 1, fontSize: "12px" }}>
                                        Selected files: {files.map(file => file.name).join(', ')}
                                    </Typography>
                                )}
                            </Box>
                        </Box>
                        <Button type="submit" variant="contained" color="primary" fullWidth>Submit</Button>
                    </Stack>
                </form>
            </Box>
        </>
    );
};

export default Counsel;