import React, { useState } from 'react';
import { Box, TextField, Button, Typography, RadioGroup, FormControlLabel, Radio, FormControl, FormLabel, Stack } from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { useNavigate } from 'react-router-dom';
import Loader from '../../loader/Loader';
import { IoCloudUploadOutline } from "react-icons/io5";
import { IoMdArrowRoundBack, IoMdLogOut } from 'react-icons/io';
import { AppBar, IconButton, Toolbar, Tooltip } from '@mui/material';
import { Dayjs } from 'dayjs';
import { sendMail } from '../../../services/sendMail';
import { notyf } from '../../../utilities/useToast';
import { getAccessToken } from '../../auth/authService';

const Ownership: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [form, setForm] = useState({
        legalEntity: '',
        jurisdiction: '',
        capital: '',
        legalShareholder: '', 
        beneficialShareholder: '',
        transactionType: '',
        otherExplain: '',
        shares: '',
        securityDesc: '',
        newLegalShareholder: '',
        newBeneficialShareholder: '',
        comments: '',
    });
    const [files, setFiles] = useState<File[]>([]);
    const [date, setDate] = useState<Dayjs | null>(null);

    const fieldLabels = {
        legalEntity: "Name of Legal Entity",
        jurisdiction: "Jurisdiction",
        capital: "Description of Capital",
        legalShareholder: "Current Legal Shareholder",
        beneficialShareholder: "Current Beneficial Shareholder",
        transactionType: "Type of Transaction",
        otherExplain: "If Other, Please explain",
        shares: "Number of shares / quotas issued / transferred / cancelled / converted",
        securityDesc: "Description of the Security following Transaction",
        newLegalShareholder: "New Legal Shareholder",
        newBeneficialShareholder: "New Beneficial Shareholder",
        comments: "Comments",
        date: "Date of Transaction",
        fileName: "Documentary Evidence"
    };

    const handleBackToHome = () => {
        navigate('/');
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (
            !form.legalEntity ||
            !form.jurisdiction ||
            !form.capital ||
            !form.legalShareholder ||
            !form.beneficialShareholder ||
            !form.transactionType ||
            !date ||
            files.length === 0
        ) {
            notyf.error('Please fill in all fields and upload at least one file.');
            return;
        }
        setIsLoading(true);
        const formData = {
            ...form,
            date: date ? date.format('YYYY-MM-DD') : '',
            fileName: files[0]?.name,
        };
        try {
            const token = await getAccessToken();
            console.log(token);
            if (!token) {
                notyf.error('Session expired. Please log in again.');
                setIsLoading(false);
                return;
            }
            await sendMail(formData, 'Change of Ownership', files, token, fieldLabels);
            notyf.success('Email sent successfully!');
            setForm({
                legalEntity: '',
                jurisdiction: '',
                capital: '',
                legalShareholder: '',
                beneficialShareholder: '',
                transactionType: '',
                otherExplain: '',
                shares: '',
                securityDesc: '',
                newLegalShareholder: '',
                newBeneficialShareholder: '',
                comments: '',
            });
            setFiles([]);
            setDate(null);
        } catch (error) {
            notyf.error('Failed to send email. Please try again.');
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            setFiles(Array.from(e.target.files));
        }
    };

    // Implement your logout logic here (e.g., clear tokens, redirect to login)
    const handleLogout = () => {
        localStorage.removeItem('access_token');
        navigate('/');
    };

    return (
        <>
            {isLoading && (<Loader />)}
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static">
                    <Toolbar sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Tooltip title="Back to Home" placement="right-start">
                                <IconButton
                                    edge="start"
                                    color="inherit"
                                    aria-label="back"
                                    onClick={handleBackToHome}
                                    sx={{ mr: 2 }}
                                >
                                    <IoMdArrowRoundBack />
                                </IconButton>
                            </Tooltip>
                            <Typography sx={{ fontSize: "16px", fontWeight: 500 }}>
                                Change of Ownership
                            </Typography>
                        </Box>
                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="logout"
                                onClick={handleLogout}
                                sx={{ ml: 2 }}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Toolbar>
                </AppBar>
            </Box>

            <Box sx={{ padding: '6px', maxWidth: 'auto', mt: 2 }}>
                <form onSubmit={handleSubmit}>
                    <Stack spacing={2}>
                        <TextField label="Name of Legal Entity" name="legalEntity" value={form.legalEntity} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Jurisdiction" name="jurisdiction" value={form.jurisdiction} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Description of Capital" name="capital" value={form.capital} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Current Legal Shareholder" name="legalShareholder" value={form.legalShareholder} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Current Beneficial Shareholder" name="beneficialShareholder" value={form.beneficialShareholder} onChange={handleChange} fullWidth size="small" />
                        <FormControl>
                            <FormLabel>Type of Transaction</FormLabel>
                            <RadioGroup row name="transactionType" value={form.transactionType} onChange={handleChange}>
                                <FormControlLabel value="Issue" control={<Radio />} label="Issue" />
                                <FormControlLabel value="Cancellation" control={<Radio />} label="Cancellation" />
                                <FormControlLabel value="Transfer" control={<Radio />} label="Transfer" />
                                <FormControlLabel value="Conversion" control={<Radio />} label="Conversion" />
                            </RadioGroup>
                        </FormControl>
                        <TextField label="If Other, Please explain" name="otherExplain" value={form.otherExplain} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Number of shares / quotas issued / transferred / cancelled / converted" name="shares" value={form.shares} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Description of the Security following Transaction" name="securityDesc" value={form.securityDesc} onChange={handleChange} fullWidth size="small" />
                        <LocalizationProvider dateAdapter={AdapterDayjs}>
                            <DatePicker
                                label="Date of Transaction"
                                value={date}
                                onChange={setDate}
                                slotProps={{ textField: { fullWidth: true, size: 'small' } }}
                            />
                        </LocalizationProvider>
                        <TextField label="New Legal Shareholder" name="newLegalShareholder" value={form.newLegalShareholder} onChange={handleChange} fullWidth size="small" />
                        <TextField label="New Beneficial Shareholder" name="newBeneficialShareholder" value={form.newBeneficialShareholder} onChange={handleChange} fullWidth size="small" />
                        <TextField label="Comments (Optional)" name="comments" value={form.comments} onChange={handleChange} fullWidth size="small" multiline minRows={2} />
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                            <Typography variant="body2">
                                Documentary Evidence
                            </Typography>
                            <Box
                                sx={{
                                    border: '2px dashed #bdbdbd',
                                    borderRadius: 2,
                                    padding: "12px 55px",
                                    textAlign: 'center',
                                    cursor: 'pointer',
                                    bgcolor: '#fafbfc',
                                    transition: 'border-color 0.2s',
                                    '&:hover': { borderColor: '#1976d2' }
                                }}
                                onClick={() => document.getElementById('file-upload-input')?.click()}
                                onDrop={e => {
                                    e.preventDefault();
                                    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                                        setFiles(Array.from(e.dataTransfer.files));
                                    }
                                }}
                                onDragOver={e => e.preventDefault()}
                            >
                                <IoCloudUploadOutline style={{ fontSize: 40, color: '#90caf9', marginBottom: '4px' }} />
                                <Typography sx={{ fontSize: "12px" }}>
                                    Drag and drop <Typography component="span" color="primary" sx={{ fontWeight: 500 }}>or <span style={{ textDecoration: 'underline', cursor: 'pointer' }}>browse</span></Typography> to upload
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 1, fontSize: "12px" }}>
                                    PDF, Word, Excel, CSV, Images up to 10MB
                                </Typography>
                                <input
                                    id="file-upload-input"
                                    type="file"
                                    hidden
                                    accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.png,.jpg,.jpeg,.gif"
                                    multiple
                                    onChange={handleFileChange}
                                />
                                {files.length > 0 && (
                                    <Typography variant="body2" color="success.main" sx={{ mt: 1, fontSize: "12px" }}>
                                        Selected files: {files.map(file => file.name).join(', ')}
                                    </Typography>
                                )}
                            </Box>
                        </Box>
                        <Button type="submit" variant="contained" color="primary" fullWidth>Submit</Button>
                    </Stack>
                </form>
            </Box>
        </>
    );
};

export default Ownership;