import React, { useState } from 'react';
import { Box, Typography, Button, AppBar, Toolbar, IconButton, TextField, RadioGroup, FormControlLabel, Radio, FormControl, FormLabel, Stack, Tooltip } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import Loader from '../../loader/Loader';
import { notyf } from '../../../utilities/useToast';
import { IoMdArrowRoundBack, IoMdLogOut } from 'react-icons/io';
import { Dayjs } from 'dayjs';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { IoCloudUploadOutline } from "react-icons/io5";
import { sendMail } from '../../../services/sendMail';
import UIText from '../../../utilities/textResource';
import { getAccessToken } from '../../auth/authService';

const Director: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [form, setForm] = useState({
        legalEntity: '',
        jurisdiction: '',
        representative: '',
        position: '',
        appointmentType: '',
        hpeEmployee: '',
        appointmentOrResignation: '',
        legalSigning: '',
        preferredSignatory: '',
    });
    const [date, setDate] = useState<Dayjs | null>(null);
    const [files, setFiles] = useState<File[]>([]);

    const handleBackToHome = () => {
        navigate('/');
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleRadioChange = (name: string) => (e: React.ChangeEvent<HTMLInputElement>) => {
        setForm({ ...form, [name]: e.target.value });
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            setFiles(Array.from(e.target.files));
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        const title = UIText.Change_of_Director_Officer.title;

        e.preventDefault();
        if (
            !form.legalEntity ||
            !form.jurisdiction ||
            !form.representative ||
            !form.position ||
            !form.appointmentType ||
            !form.hpeEmployee ||
            !form.appointmentOrResignation ||
            !date ||
            !form.legalSigning ||
            !form.preferredSignatory ||
            files.length === 0
        ) {
            notyf.error('Please fill in all required fields and upload at least one file.');
            return;
        }
        setIsLoading(true);
        const allValues = {
            ...form,
            date: date.format('YYYY-MM-DD'),
            fileName: files[0].name,
        };
        const fieldLabels = {
            legalEntity: "Name of Legal Entity",
            jurisdiction: "Jurisdiction",
            representative: "Full Name of Legal Representative",
            position: "Appointment Type",
            appointmentType: "Type of Position",
            hpeEmployee: "Is this person an HPE Employee?",
            appointmentOrResignation: "Appointment or Resignation?",
            date: "Date of Appointment / Resignation",
            legalSigning: "Legal Signing Authority",
            preferredSignatory: "Preferred Signatory for IC Agreement",
            fileName: "Documentary Evidence"
        };
        try {
            const token = await getAccessToken();
            if (!token) throw new Error('No access token found');
            await sendMail(allValues, title, files, token, fieldLabels);
            notyf.success('Email sent successfully!');
            setForm({
                legalEntity: '',
                jurisdiction: '',
                representative: '',
                position: '',
                appointmentType: '',
                hpeEmployee: '',
                appointmentOrResignation: '',
                legalSigning: '',
                preferredSignatory: '',
            });
            setDate(null);
            setFiles([]);
        } catch (error) {
            notyf.error('Failed to send email. Please try again.');
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    };

    // Implement your logout logic here (e.g., clear tokens, redirect to login)
    const handleLogout = () => {
        localStorage.removeItem('access_token');
        navigate('/');
    };

    return (
        <>
            {isLoading && (<Loader />)}
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static">
                    <Toolbar sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Tooltip title="Back to Home" placement="right-start">
                                <IconButton
                                    edge="start"
                                    color="inherit"
                                    aria-label="back"
                                    onClick={handleBackToHome}
                                    sx={{ mr: 2 }}
                                >
                                    <IoMdArrowRoundBack />
                                </IconButton>
                            </Tooltip>
                            <Typography sx={{ fontSize: "16px", fontWeight: 500 }}>
                                Change of Director / Officer
                            </Typography>
                        </Box>
                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="logout"
                                onClick={handleLogout}
                                sx={{ ml: 2 }}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Toolbar>
                </AppBar>
            </Box>

            <Box sx={{ padding: '6px', maxWidth: 'auto', mt: 2 }}>
                <form onSubmit={handleSubmit}>
                    <Stack spacing={2}>
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                            <Box flex={2}>
                                <TextField label="Name of Legal Entity" name="legalEntity" value={form.legalEntity} onChange={handleInputChange} fullWidth size="small" />
                            </Box>
                            <Box flex={1}>
                                <TextField label="Jurisdiction" name="jurisdiction" value={form.jurisdiction} onChange={handleInputChange} fullWidth size="small" />
                            </Box>
                        </Stack>
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                            <Box flex={2}>
                                <TextField label="Full Name of Legal Representative" name="representative" value={form.representative} onChange={handleInputChange} fullWidth size="small" />
                            </Box>
                            <Box flex={1}>
                                <TextField label="Appointment Type" name="position" value={form.position} onChange={handleInputChange} fullWidth size="small" multiline minRows={2} />
                            </Box>
                        </Stack>
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                            <Box flex={1}>
                                <FormControl fullWidth>
                                    <FormLabel>Type of Position</FormLabel>
                                    <RadioGroup row name="appointmentType" value={form.appointmentType} onChange={handleRadioChange('appointmentType')}>
                                        <FormControlLabel value="Director" control={<Radio />} label="Director" />
                                        <FormControlLabel value="Management Board" control={<Radio />} label="Management Board" />
                                        <FormControlLabel value="Supervisory Board" control={<Radio />} label="Supervisory Board" />
                                        <FormControlLabel value="Officers" control={<Radio />} label="Officers" />
                                    </RadioGroup>
                                </FormControl>
                            </Box>
                            <Box flex={1}>
                                <FormControl fullWidth>
                                    <FormLabel>Is this person an HPE Employee?</FormLabel>
                                    <RadioGroup row name="hpeEmployee" value={form.hpeEmployee} onChange={handleRadioChange('hpeEmployee')}>
                                        <FormControlLabel value="Yes" control={<Radio />} label="Yes" />
                                        <FormControlLabel value="No" control={<Radio />} label="No" />
                                    </RadioGroup>
                                </FormControl>
                            </Box>
                            <Box flex={1}>
                                <FormControl fullWidth>
                                    <FormLabel>Appointment or Resignation?</FormLabel>
                                    <RadioGroup row name="appointmentOrResignation" value={form.appointmentOrResignation} onChange={handleRadioChange('appointmentOrResignation')}>
                                        <FormControlLabel value="Appointment" control={<Radio />} label="Appointment" />
                                        <FormControlLabel value="Resignation" control={<Radio />} label="Resignation" />
                                    </RadioGroup>
                                </FormControl>
                            </Box>
                        </Stack>
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                            <Box flex={1}>
                                <LocalizationProvider dateAdapter={AdapterDayjs}>
                                    <DatePicker
                                        label="Date of Appointment / Resignation"
                                        value={date}
                                        onChange={setDate}
                                        slotProps={{ textField: { fullWidth: true, size: 'small' } }}
                                    />
                                </LocalizationProvider>
                            </Box>
                            <Box flex={1}>
                                <FormControl fullWidth>
                                    <FormLabel>Legal Signing Authority (Appointments Only)</FormLabel>
                                    <RadioGroup row name="legalSigning" value={form.legalSigning} onChange={handleRadioChange('legalSigning')}>
                                        <FormControlLabel value="Joint" control={<Radio />} label="Joint" />
                                        <FormControlLabel value="Individual" control={<Radio />} label="Individual" />
                                    </RadioGroup>
                                </FormControl>
                            </Box>
                        </Stack>
                        <TextField 
                            label="Preferred Signatory for IC Agreement" 
                            name="preferredSignatory" 
                            value={form.preferredSignatory} 
                            onChange={handleInputChange} 
                            fullWidth 
                            size="small" 
                        />
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="center">
                            <Box
                                sx={{
                                    border: '2px dashed #bdbdbd',
                                    borderRadius: 2,
                                    padding: "12px 55px",
                                    textAlign: 'center',
                                    cursor: 'pointer',
                                    bgcolor: '#fafbfc',
                                    transition: 'border-color 0.2s',
                                    '&:hover': { borderColor: '#1976d2' }
                                }}
                                onClick={() => document.getElementById('file-upload-input')?.click()}
                                onDrop={e => {
                                    e.preventDefault();
                                    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                                        setFiles(Array.from(e.dataTransfer.files));
                                    }
                                }}
                                onDragOver={e => e.preventDefault()}
                            >
                                <IoCloudUploadOutline style={{ fontSize: 40, color: '#90caf9', marginBottom: '4px' }} />
                                <Typography sx={{ fontSize: "12px" }}>
                                    Drag and drop <Typography component="span" color="primary" sx={{ fontWeight: 500 }}>or <span style={{ textDecoration: 'underline', cursor: 'pointer' }}>browse</span></Typography> to upload
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 1, fontSize: "12px" }}>
                                    PDF, Word, Excel, CSV, Images up to 10MB
                                </Typography>
                                <input
                                    id="file-upload-input"
                                    type="file"
                                    hidden
                                    accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.png,.jpg,.jpeg,.gif"
                                    multiple
                                    onChange={handleFileChange}
                                />
                                {files.length > 0 && (
                                    <Typography variant="body2" color="success.main" sx={{ mt: 1, fontSize: "12px" }}>
                                        Selected files: {files.map(file => file.name).join(', ')}
                                    </Typography>
                                )}
                            </Box>
                            <Box flex={1}>
                                <Typography variant="body2" sx={{ mt: 1 }}>
                                    Please Attach any Supporting Documents
                                </Typography>
                            </Box>
                        </Stack>
                        <Button type="submit" variant="contained" color="primary" fullWidth>
                            Submit
                        </Button>
                    </Stack>
                </form>
            </Box>
        </>
    );
};

export default Director;